var noise_texture_default = "export function getShaderNoiseTexture(): HTMLImageElement | undefined {\n  if (typeof window === 'undefined') {\n    return undefined;\n  }\n\n  const img = new Image();\n  img.src = noiseSrc;\n  return img;\n}\n\nconst noiseSrc =\n  'data:image/png;base64,';\n";
