//#region src/lib/codegen/export/registry.ts
/**
* The shared shader-mount registry item. Consumers install this once;
* subsequent shader items depend on it via `registryDependencies`.
*
* The mount source plus its three dependencies (runtime-shell, image helper,
* noise texture, and the UniformSpec types) are bundled together so the
* installed file works without import-path surgery.
*/
function buildShaderMountRegistryItem() {
	const stripImports = (src) => src.replace(/^\s*import [^\n]+\n/gm, "");
	const typesSrc = stripImports(types_default);
	const uniformGlType = typesSrc.match(/export type UniformGlType[\s\S]+?(?=\n\n)/)?.[0];
	const uniformSpec = typesSrc.match(/export interface UniformSpec[\s\S]+?\n\}/)?.[0];
	return {
		$schema: "https://ui.shadcn.com/schema/registry-item.json",
		name: "shader-mount",
		type: "registry:lib",
		description: "Portable WebGL2 runtime that mounts a generated shader bundle (vertex + fragment passes + uniform metadata) onto a canvas.",
		files: [{
			path: "lib/shader-mount.ts",
			content: `// Auto-generated bundle for shadcn install. Single-file portable runtime.
// Source of truth: shader-composer's @/lib/codegen/runtime tree.

${[
				"// --- types ---",
				uniformGlType ?? "",
				uniformSpec ?? "",
				"// --- noise texture ---",
				stripImports(noise_texture_default),
				"// --- image cache + binding helpers ---",
				stripImports(export_image_helper_default),
				"// --- multi-pass GL pipeline kernel ---",
				stripImports(runtime_shell_default),
				"// --- canvas-mount surface ---",
				stripImports(shader_mount_default)
			].filter(Boolean).join("\n\n")}
`,
			type: "registry:lib"
		}]
	};
}
